package e.e.a;
import android.content.*;import android.media.*;import android.net.Uri;import java.io.*;import java.net.*;import java.nio.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;import org.json.*;
/** Authenticated finite HLS download and lossless MP4 remux. No playback state is used. */
final class Mp4Transfer115 {
 final DownloadJobs115.Job job;final Context context;final File folder;String cookie;final Map<String,byte[]> keys=new HashMap<>();volatile HttpURLConnection connection;
 Mp4Transfer115(Context c,DownloadJobs115.Job j){context=c;job=j;folder=new File(c.getCacheDir(),"mp4-"+j.token);}
 void check()throws IOException{if(job.cancelled||job.paused||Thread.currentThread().isInterrupted())throw new InterruptedIOException();}
 HttpURLConnection open(URL url,long length,long offset)throws Exception{
  for(int attempt=0;attempt<6;attempt++){check();Mp4Playlist115.resolve(url,url.toString());HttpURLConnection c=(HttpURLConnection)url.openConnection();connection=c;
   try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","Mozilla/5.0 (Linux; Android) AppleWebKit/537.36 Chrome/120.0 Mobile Safari/537.36");c.setRequestProperty("Referer","https://www.nicovideo.jp/");c.setRequestProperty("Origin","https://www.nicovideo.jp");String scoped=SecurityPolicy240.cookie(url.toString(),cookie,null);if(!scoped.isEmpty())c.setRequestProperty("Cookie",scoped);if(length>0)c.setRequestProperty("Range","bytes="+offset+"-"+(offset+length-1));int status=c.getResponseCode();if(status==301||status==302||status==303||status==307||status==308){String next=c.getHeaderField("Location");if(next==null)throw new IOException("配信先を取得できません");url=Mp4Playlist115.resolve(url,next);c.disconnect();connection=null;continue;}if(status<200||status>=300||length>0&&status!=206)throw new IOException("動画取得に失敗しました (HTTP "+status+")");if(length>0){String wanted="bytes "+offset+"-"+(offset+length-1)+"/",actual=c.getHeaderField("Content-Range");if(actual==null||!actual.startsWith(wanted))throw new IOException("配信範囲が一致しません");}return c;
   }catch(Exception e){c.disconnect();connection=null;throw e;}
  }throw new IOException("配信先の転送が多すぎます");
 }
 byte[] small(URL url,int limit)throws Exception{HttpURLConnection c=open(url,-1,0);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){check();if(out.size()+n>limit)throw new IOException("配信情報が大きすぎます");out.write(b,0,n);}return out.toByteArray();}finally{c.disconnect();connection=null;}}
 String text(URL u)throws Exception{return new String(small(u,4*1024*1024),"UTF-8");}
 File run(Object model)throws Exception{
  check();JSONObject watch=GuestWatch.watch(model,job.id);if(watch==null)throw new IOException("動画情報を取得できません。視聴権限や通信を確認してください");
  JSONObject video=watch.getJSONObject("video");job.title=video.optString("title",job.title);JSONObject domand=watch.getJSONObject("media").getJSONObject("domand");JSONArray videos=domand.getJSONArray("videos"),audios=domand.getJSONArray("audios");JSONObject selected=null;int best=-1;for(int i=0;i<videos.length();i++){JSONObject v=videos.getJSONObject(i);if(!v.optBoolean("isAvailable"))continue;int height=v.optInt("height",height(v.optString("id")));if(job.height>0&&(height<=0||height>job.height))continue;if(height>best){selected=v;best=height;}}
  if(selected==null)throw new IOException("指定した画質を取得できません");String audio=null;for(int i=0;i<audios.length();i++)if(audios.getJSONObject(i).optBoolean("isAvailable")){audio=audios.getJSONObject(i).getString("id");break;}if(audio==null)throw new IOException("音声を取得できません");job.quality=best>0?best+"p":selected.getString("id");
  JSONArray outputs=new JSONArray().put(new JSONArray().put(selected.getString("id")).put(audio));String api="https://nvapi.nicovideo.jp/v1/watch/"+Uri.encode(job.id)+"/access-rights/hls?actionTrackId="+Uri.encode(watch.getJSONObject("client").getString("watchTrackId"));
  String response=Quality195.request(model,api,new JSONObject().put("outputs",outputs).toString(),domand.getString("accessRightKey"));check();String content=new JSONObject(response).getJSONObject("data").getString("contentUrl");cookie=SecurityPolicy240.cookie(content,VideoDetails.cookie(),ModernPlayback.domandCookie);
  List<Mp4Playlist115.Plan> plans=Mp4Playlist115.load(new URL(content),u->text(u));job.total=0;for(Mp4Playlist115.Plan p:plans){job.assets+=p.segments.size();if(p.bytes<0||job.total<0)job.total=-1;else job.total+=p.bytes;}if(!folder.isDirectory()&&!folder.mkdirs())throw new IOException("作業フォルダを作成できません");List<File> tracks=new ArrayList<>();int index=0;job.phase="ダウンロード中";
  for(Mp4Playlist115.Plan plan:plans){File dest=new File(folder,"track-"+(index++));try(OutputStream out=new BufferedOutputStream(new FileOutputStream(dest))){for(Mp4Playlist115.Segment s:plan.segments){check();binary(s,out);job.finishedAssets++;}}tracks.add(dest);}
  job.phase="MP4作成中";DownloadJobs115.changed(context);File output=new File(folder,"complete.mp4");mux(tracks,output);return output;
 }
 static int height(String id){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?:^|[^0-9])([0-9]{3,4})p(?:[^0-9]|$)").matcher(id);return m.find()?Integer.parseInt(m.group(1)):0;}
 void binary(Mp4Playlist115.Segment s,OutputStream out)throws Exception{byte[] key=null;if(s.key!=null){String name=s.key.toString();key=keys.get(name);if(key==null){key=small(s.key,16);if(key.length!=16)throw new IOException("配信キーが不正です");keys.put(name,key);}}
  HttpURLConnection c=open(s.url,s.length,s.offset);long got=0,expected=s.length>0?s.length:c.getContentLengthLong();job.assetBytes=0;job.assetSize=expected;try(InputStream raw=c.getInputStream()){
   Cipher cipher=null;if(key!=null){cipher=Cipher.getInstance("AES/CBC/PKCS5Padding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new IvParameterSpec(s.iv));}
   byte[] buffer=new byte[65536];int n;while((n=raw.read(buffer))!=-1){check();got+=n;if(expected>0&&got>expected)throw new IOException("配信データが長すぎます");job.bytes+=n;job.assetBytes=got;if(cipher==null)out.write(buffer,0,n);else{byte[] plain=cipher.update(buffer,0,n);if(plain!=null)out.write(plain);}DownloadWorker115.progress();}if(expected>=0&&got!=expected)throw new IOException("配信データが途中で終了しました");if(cipher!=null)out.write(cipher.doFinal());
  }finally{c.disconnect();connection=null;}}
 static final class Track{MediaExtractor extractor;int target;long first,last=Long.MIN_VALUE;Track(MediaExtractor e,int t){extractor=e;target=t;first=e.getSampleTime();}}
 void mux(List<File> files,File output)throws Exception{if(!files.isEmpty()&&FragmentedMp4117.isFragmented(files.get(0))){FragmentMux117.mux(this,files,output);return;}platformMux(files,output);}
 void platformMux(List<File> files,File output)throws Exception{List<MediaExtractor> opened=new ArrayList<>();List<Track> tracks=new ArrayList<>();MediaMuxer mux=null;boolean started=false,complete=false;try{mux=new MediaMuxer(output.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);boolean hasVideo=false,hasAudio=false;int capacity=4*1024*1024;
   for(File file:files){MediaExtractor probe=new MediaExtractor();opened.add(probe);probe.setDataSource(file.getAbsolutePath());for(int i=0;i<probe.getTrackCount();i++){MediaFormat format=probe.getTrackFormat(i);String mime=format.getString(MediaFormat.KEY_MIME);if(mime==null||!mime.startsWith("video/")&&!mime.startsWith("audio/"))continue;boolean isVideo=mime.startsWith("video/");if(isVideo?hasVideo:hasAudio)continue;if(format.containsKey(MediaFormat.KEY_MAX_INPUT_SIZE))capacity=Math.max(capacity,format.getInteger(MediaFormat.KEY_MAX_INPUT_SIZE));MediaExtractor e=new MediaExtractor();opened.add(e);e.setDataSource(file.getAbsolutePath());e.selectTrack(i);Track track=new Track(e,-1);if(track.first<0)continue;track.target=mux.addTrack(format);tracks.add(track);if(isVideo)hasVideo=true;else hasAudio=true;}}
   if(!hasVideo||!hasAudio)throw new IOException("映像または音声をMP4へ格納できません");if(capacity>64*1024*1024)throw new IOException("動画フレームが大きすぎます");long origin=Long.MAX_VALUE;for(Track t:tracks){if(t.first<0)throw new IOException("動画トラックが空です");origin=Math.min(origin,t.first);}mux.start();started=true;ByteBuffer data=ByteBuffer.allocateDirect(capacity);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();
   while(true){check();Track next=null;for(Track t:tracks)if(t.extractor.getSampleTime()>=0&&(next==null||t.extractor.getSampleTime()<next.extractor.getSampleTime()))next=t;if(next==null)break;data.clear();long sampleSize=next.extractor.getSampleSize();if(sampleSize>capacity)throw new IOException("動画フレームが大きすぎます");int n=next.extractor.readSampleData(data,0);if(n<0)throw new IOException("動画データが途中で終了しました");long time=next.extractor.getSampleTime()-origin;if(time<0)throw new IOException("動画の時刻が不正です");int flags=next.extractor.getSampleFlags();if((flags&MediaExtractor.SAMPLE_FLAG_ENCRYPTED)!=0)throw new IOException("暗号化されたトラックは保存できません");info.set(0,n,time,(flags&MediaExtractor.SAMPLE_FLAG_SYNC)!=0?MediaCodec.BUFFER_FLAG_KEY_FRAME:0);mux.writeSampleData(next.target,data,info);next.last=time;next.extractor.advance();}
   mux.stop();started=false;for(Track t:tracks)if(t.last<0)throw new IOException("MP4トラックが空です");complete=true;
  }finally{for(MediaExtractor e:opened)e.release();if(mux!=null){if(started)try{mux.stop();}catch(Exception ignored){}mux.release();}if(!complete)output.delete();}}
 void cancel(){HttpURLConnection c=connection;if(c!=null)c.disconnect();}
 void clean(){File[] files=folder.listFiles();if(files!=null)for(File f:files)f.delete();folder.delete();cookie=null;for(byte[] key:keys.values())Arrays.fill(key,(byte)0);keys.clear();}
}
